  cycle_nudge_luteal_sleep_body: "Il progesterone alza la temperatura corporea e frammenta il sonno. Una stanza più fresca e una sera più rilassata stabilizzano l’umore più di quanto immagini.",
  cycle_nudge_luteal_move_headline: "Una passeggiata batte *la spirale*",
  cycle_nudge_luteal_move_body: "I cali di fine fase luteale sono ormonali, non un giudizio sulla tua vita. Venti minuti di luce e movimento rimettono in sesto meglio dello scrolling.",
  cycle_nudge_fertility_follicular_headline: "La tua finestra *si avvicina*",
  cycle_nudge_fertility_follicular_body: "Gli estrogeni crescono verso l’ovulazione. I cinque giorni prima dell’ovulazione sono la tua finestra fertile — gli spermatozoi possono aspettare l’ovulo così a lungo.",
  cycle_nudge_fertility_luteal_headline: "La finestra *si è chiusa*",
  cycle_nudge_fertility_luteal_body: "L’ovulo vive solo 12–24 ore, quindi questa parte del ciclo ha poche probabilità. Se hai fatto test o programmato i rapporti, ora non resta che aspettare.",
  cycle_nudge_fertility_menstruation_headline: "Inizia un ciclo *nuovo*",
  cycle_nudge_fertility_menstruation_body: "Il primo giorno azzera il conteggio. La tua prossima finestra fertile è tra circa due settimane — un tratto tranquillo per riposare e prepararti prima che si apra.",
  cycle_nudge_reflect_mood_headline: "Come ti *senti* oggi?",
  cycle_nudge_reflect_mood_body: "Un rapido controllo dell’umore costruisce il quadro nel tempo — gli schemi per fase si vedono meglio dopo qualche ciclo registrato.",
  cycle_nudge_reflect_symptom_headline: "Noti *qualcosa* oggi?",
  cycle_nudge_reflect_symptom_body: "Crampi, seno dolente, mal di testa? Registrare i sintomi aiuta te e il tuo medico a capire cosa è tipico per te e cosa no.",
  cycle_nudge_reflect_energy_headline: "A che punto è la tua *energia*?",
  cycle_nudge_reflect_energy_body: "L’energia cala naturalmente prima delle mestruazioni. Annotarla oggi ti aiuta a organizzarti secondo il tuo ritmo invece di combatterlo.",
  cycle_nudge_nutrition_luteal_headline: "Scegli il *magnesio*",
  cycle_nudge_nutrition_luteal_body: "Cioccolato fondente, mandorle, semi di zucca e banane alleviano i crampi e stabilizzano l’umore nella seconda metà del ciclo. Abbina carboidrati complessi per attenuare le voglie.",
  cycle_nudge_nutrition_ovulation_headline: "Nutri *l’ovulo*",
  cycle_nudge_nutrition_ovulation_body: "Cibi ricchi di antiossidanti — frutti di bosco, verdure a foglia, frutta secca — sostengono la qualità dell’ovulo. Lo zinco (semi di zucca, ceci) conta di più attorno all’ovulazione.",
  cycle_nudge_edu_menstruation_headline: "Le mestruazioni sono il *primo* giorno",
  cycle_nudge_edu_menstruation_body: "Il giorno uno del ciclo è il primo giorno di sanguinamento vero, non di spotting. È l’ancora da cui si conta ogni previsione — registrarlo con precisione affina tutto.",
  cycle_nudge_edu_follicular_headline: "Un follicolo *vince*",
  cycle_nudge_edu_follicular_body: "Ogni ciclo iniziano a crescere diversi follicoli, ma di solito solo uno matura e rilascia un ovulo. Sono gli estrogeni in aumento a guidare questa selezione.",
  cycle_nudge_edu_ovulation_headline: "Un evento di *36 ore*",
  cycle_nudge_edu_ovulation_body: "L’ovulazione in sé è breve — il picco di LH innesca il rilascio entro circa 24–36 ore. Per questo i test LH servono a cogliere il picco, non il rilascio.",
  cycle_nudge_edu_luteal_headline: "L’attesa di *due settimane*",
  cycle_nudge_edu_luteal_body: "La fase luteale è molto regolare — di solito 12–14 giorni a prescindere dalla durata del ciclo. Gran parte della variazione del ciclo viene dalla prima metà, non da questa.",
  cycle_pillar_fertility: "Basi della fertilità",
