  cycle_conf_calendar: "Stima basata sul calendario. Aggiungi BBT + LH per i prossimi 3 giorni per affinare la previsione.",
  cycle_conf_bbt_only: "Calendario + la tua BBT. Aggiungi i test LH per portare l’affidabilità oltre il 90%.",
  cycle_conf_bbt_lh: "Calendario + BBT + LH — l’affidabilità è alta. In attesa dello shift di temperatura dopo l’ovulazione per fissare il picco.",
  cycle_conf_shift_confirmed: "Shift della BBT confermato. Il picco passato è fissato. Le finestre future restano basate sul calendario.",
