  sw2_leap19_name: "Eventi",
  sw2_leap19_desc: "Capire che le azioni avvengono in sequenza",
  sw2_leap19_brain: "Verso questo periodo i bambini iniziano spesso a vedere il mondo come una serie di eventi e non come un grande sfocato. Le azioni hanno un inizio, uno svolgimento e una fine. È l’inizio del pensiero di causa ed effetto, ed è per questo che tutto può sembrare all’improvviso affascinante.",
  sw2_leap19_tip: "Fai semplici giochi di causa ed effetto, come il cucù: il bebè sta imparando che gli eventi hanno esiti prevedibili.",
  sw2_leap19_ph0: "Attaccato a te, piange quando lo metti giù, sonno disturbato. Il bebè può sentirsi stanco per tante novità tutte insieme.",
  sw2_leap19_ph1: "Il bebè è spesso impegnato a collegare ogni azione a ciò che succede dopo: spingere, lasciar cadere, osservare da vicino.",
  sw2_leap19_ph2: "Compare l’allungarsi con intenzione, insieme ai primi segni di permanenza dell’oggetto: il bebè cerca ciò che è caduto.",
  sw2_leap19_sg0: "Più ansia da separazione",
  sw2_leap19_sg1: "Molto attaccato",
  sw2_leap19_sg2: "Piange quando cade un giocattolo",
  sw2_leap19_sg3: "Fa resistenza ai sonnellini",
  sw2_leap19_sg4: "Chiede interazione",
  sw2_leap19_sg5: "Si frustra quando la routine cambia",
  sw2_leap19_sk0: "Si allunga e afferra di proposito",
  sw2_leap19_sk1: "Scuote e batte i giochi",
  sw2_leap19_sk2: "Riconosce i giochi",
  sw2_leap19_sk3: "Capisce «su» e «giù»",
  sw2_leap19_sk4: "Segue con gli occhi gli oggetti in movimento",
  sw2_leap19_sk5: "Ride alle sorprese",
  sw2_leap19_ac0: "Giochi di cucù e nascondino",
  sw2_leap19_ac1: "Far rotolare una palla avanti e indietro",
  sw2_leap19_ac2: "Giochi semplici di causa-effetto (premi = suono)",
  sw2_leap19_ac3: "Racconta la routine quotidiana passo dopo passo",
  sw2_leap5_name: "Sensazioni che cambiano",
  sw2_leap5_desc: "Il bebè scopre un mondo di sensi più ricco",
  sw2_leap5_brain: "In questo periodo il tuo bebè può iniziare a cogliere molti più dettagli con i sensi: immagini più nitide, suoni più ricchi, nuove sensazioni nel corpo. Può essere tanto, e insieme meraviglioso.",
  sw2_leap5_ph0: "Più pianto, più bisogno di contatto e sonno agitato sono comuni. Il bebè può ricevere molte nuove informazioni sensoriali.",
  sw2_leap5_ph1: "Il bebè assorbe tante immagini e suoni nuovi. L’irrequietezza può avere un picco prima di calmarsi.",
  sw2_leap5_ph2: "La nuova consapevolezza sensoriale sboccia: noterai periodi di veglia più lunghi e uno sguardo più intenzionale.",
  sw2_leap5_sg0: "Piange più del solito",
  sw2_leap5_sg1: "Vuole mangiare in continuazione",
  sw2_leap5_sg2: "Più difficile da calmare",
  sw2_leap5_sg3: "Preferisce stare vicino",
  sw2_leap5_sg4: "Si spaventa più facilmente",
  sw2_leap5_sg5: "Non ama essere spogliato",
  sw2_leap5_sk0: "Reagisce a luce e suoni",
  sw2_leap5_sk1: "Segue con lo sguardo in modo più fluido",
  sw2_leap5_sk2: "Primo sorriso sociale",
  sw2_leap5_sk3: "Più momenti di veglia attenta",
  sw2_leap5_sk4: "Si volta verso la tua voce",
  sw2_leap5_sk5: "Nota i motivi ad alto contrasto",
  sw2_leap5_ac0: "Tieni il bebè rivolto in fuori per esplorare la stanza",
  sw2_leap5_ac1: "Mostra carte in bianco e nero ad alto contrasto",
  sw2_leap5_ac2: "Racconta ad alta voce tutto quello che fai",
  sw2_leap5_ac3: "Dolce massaggio al bebè nei momenti di calma",
  sw2_leap5_tip: "Il contatto pelle a pelle è prezioso adesso. Il porta-bebè e le dolci cullate possono alleviare i giorni più agitati.",
