  sw3_ins_ageYr: "{{n}} a",
  sw3_ins_narrTop: "L’attività più registrata di {{name}} è {{type}}, con {{n}} voci questo mese.",
  sw3_ins_narrStreak: "Stai registrando da {{n}} giorni di fila: continua così!",
