  sw2_kh_sqPoorTag: "Sotto l’obiettivo di recente",
  sw2_kh_sqPoorBlurb: "Molte notti sono state corte o interrotte. Se va avanti da una settimana e ti stai chiedendo perché, parlarne con il pediatra può aiutare: malattia, dentizione e cambi di orari possono influire.",
